import java.util.*;

class Solution {
    private Set<String> set = new LinkedHashSet<>();

    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        dfs(candidates, target, new ArrayList<>());

        List<List<Integer>> result = new ArrayList<>();
        for (String key : set) {
            List<Integer> combo = new ArrayList<>();
            if (key.isEmpty()) continue;
            for (String part : key.split(",")) combo.add(Integer.parseInt(part));
            result.add(combo);
        }
        return result;
    }

    private void dfs(int[] candidates, int remaining, List<Integer> path) {
        if (remaining == 0) {
            List<Integer> copy = new ArrayList<>(path);
            Collections.sort(copy);          // 排序后再拼串才能去重
            StringBuilder sb = new StringBuilder();
            for (int v : copy) {
                if (sb.length() > 0) sb.append(",");
                sb.append(v);
            }
            set.add(sb.toString());
            return;
        }
        if (remaining < 0) return;

        for (int v : candidates) {
            path.add(v);
            dfs(candidates, remaining - v, path);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    private List<List<Integer>> result = new ArrayList<>();
    private List<Integer> path = new ArrayList<>();

    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);      // 剪枝的前提
        dfs(candidates, 0, target);
        return result;
    }

    private void dfs(int[] candidates, int start, int remaining) {
        if (remaining == 0) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            if (candidates[i] > remaining) break;   // 后面的更大，全跳过

            path.add(candidates[i]);
            dfs(candidates, i, remaining - candidates[i]);   // 传 i，可重复用
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>>[] dp = new List[target + 1];
        for (int s = 0; s <= target; s++) dp[s] = new ArrayList<>();
        dp[0].add(new ArrayList<>());       // 凑出 0 的方案

        for (int c : candidates) {          // 外层候选，保证是组合不是排列
            for (int s = c; s <= target; s++) {
                for (List<Integer> combo : dp[s - c]) {
                    List<Integer> next = new ArrayList<>(combo);
                    next.add(c);
                    dp[s].add(next);
                }
            }
        }
        return dp[target];
    }
}
